void PageHandler_GetGifsByIds_ProxyToResponder::Run(
    Status in_status, std::vector<GifResponsePtr> in_selected_gifs) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send reply emoji_picker::mojom::PageHandler::GetGifsByIds", "async_response_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("status"), in_status,
                        "<value of type Status>");
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("selected_gifs"), in_selected_gifs,
                        "<value of type std::vector<GifResponsePtr>>");
   });
#endif
  
  const uint32_t kFlags = mojo::Message::kFlagIsResponse |
      ((is_sync_) ? mojo::Message::kFlagIsSync : 0) |
      ((true) ? 0 : mojo::Message::kFlagNoInterrupt) |
      ((false) ? mojo::Message::kFlagIsUrgent : 0);
  
  mojo::Message message(
      internal::kPageHandler_GetGifsByIds_Name, kFlags, 0, 0, nullptr);
  mojo::internal::MessageFragment<
      ::emoji_picker::mojom::internal::PageHandler_GetGifsByIds_ResponseParams_Data> params(
          message);
  params.Allocate();
  mojo::internal::Serialize<::emoji_picker::mojom::Status>(
      in_status, &params->status);
  mojo::internal::MessageFragment<
      typename decltype(params->selected_gifs)::BaseType>
      selected_gifs_fragment(params.message());
  constexpr const mojo::internal::ContainerValidateParams& selected_gifs_validate_params =
      mojo::internal::GetArrayValidator<0, false, nullptr>();
  mojo::internal::Serialize<mojo::ArrayDataView<::emoji_picker::mojom::GifResponseDataView>>(
      in_selected_gifs, selected_gifs_fragment, &selected_gifs_validate_params);
  params->selected_gifs.Set(
      selected_gifs_fragment.is_null() ? nullptr : selected_gifs_fragment.data());
  MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
      params->selected_gifs.is_null(),
      mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
      "null selected_gifs in ");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(PageHandler::Name_);
  message.set_method_name("GetGifsByIds");
#endif

  message.set_request_id(request_id_);
  message.set_trace_nonce(trace_nonce_);
  ::mojo::internal::SendMojoMessage(*responder_, message);
  // SendMojoMessage() fails silently if the responder connection is closed,
  // or if the message is malformed.
  //
  // TODO(darin): If Accept() returns false due to a malformed message, that
  // may be good reason to close the connection. However, we don't have a
  // way to do that from here. We should add a way.
  responder_ = nullptr;
}

